import{_ as a,H as n,f as p,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"28 | 跑通系统：填业务层，看见混沌测试真的跑起来","description":"","frontmatter":{},"headers":[{"level":2,"title":"27 讲漏了什么","slug":"_27-讲漏了什么","link":"#_27-讲漏了什么","children":[]},{"level":2,"title":"把业务层填进去","slug":"把业务层填进去","link":"#把业务层填进去","children":[{"level":3,"title":"场景库 scenarios/","slug":"场景库-scenarios","link":"#场景库-scenarios","children":[]},{"level":3,"title":"报告模板 templates/report.md.j2","slug":"报告模板-templates-report-md-j2","link":"#报告模板-templates-report-md-j2","children":[]},{"level":3,"title":"套件配置 config.yml","slug":"套件配置-config-yml","link":"#套件配置-config-yml","children":[]},{"level":3,"title":"GitHub Deploy Key 和 test-reports 仓库","slug":"github-deploy-key-和-test-reports-仓库","link":"#github-deploy-key-和-test-reports-仓库","children":[]},{"level":3,"title":"cron.yml 三档调度","slug":"cron-yml-三档调度","link":"#cron-yml-三档调度","children":[]}]},{"level":2,"title":"让 Hermes 跑起来","slug":"让-hermes-跑起来","link":"#让-hermes-跑起来","children":[{"level":3,"title":"先看一眼 Tool 和 Skill 都加载了","slug":"先看一眼-tool-和-skill-都加载了","link":"#先看一眼-tool-和-skill-都加载了","children":[]},{"level":3,"title":"用对话跑一次完整测试","slug":"用对话跑一次完整测试","link":"#用对话跑一次完整测试","children":[]}]},{"level":2,"title":"接下来怎么变成 7×24","slug":"接下来怎么变成-7×24","link":"#接下来怎么变成-7×24","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/28｜跑通系统：填业务层，看见混沌测试真的跑起来.md","filePath":"ClaudeCode企业级老项目改造实战/28｜跑通系统：填业务层，看见混沌测试真的跑起来.md","lastUpdated":1795530109000}'),t={name:"ClaudeCode企业级老项目改造实战/28｜跑通系统：填业务层，看见混沌测试真的跑起来.md"};function e(l,s,o,h,r,c){return n(),p("div",null,[...s[0]||(s[0]=[i(`<h1 id="_28-跑通系统-填业务层-看见混沌测试真的跑起来" tabindex="-1">28 | 跑通系统：填业务层，看见混沌测试真的跑起来 <a class="header-anchor" href="#_28-跑通系统-填业务层-看见混沌测试真的跑起来" aria-label="Permalink to &quot;28 | 跑通系统：填业务层，看见混沌测试真的跑起来&quot;">​</a></h1><p>你好，我是 Robert。</p><p>上一讲代码长出来了，5 个 Tool 和 SKILL.md 骨架全部就位，每个 Tool 都通过单点对话验证过。但这套系统现在还跑不起来，具体场景没填、报告模板空着、Deploy Key 没生成、Cron没装。这一讲把这些填完，然后用一段对话把整个系统真的跑一遍。</p><h2 id="_27-讲漏了什么" tabindex="-1">27 讲漏了什么 <a class="header-anchor" href="#_27-讲漏了什么" aria-label="Permalink to &quot;27 讲漏了什么&quot;">​</a></h2><p>回头看 27 讲末尾留的五个待办：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景库 scenarios/ 是空的，Skill 没拿到具体场景没法跑完整流程。</span></span>
<span class="line"><span>报告模板 report.md.j2 没写，report.py 调 Jinja2 加载会报模板找不到。</span></span>
<span class="line"><span>套件配置 config.yml 是空的，SDK 矩阵、Chaosd 端点、报告仓库地址都没值。</span></span></code></pre></div><ul><li><p>GitHub Deploy Key 和 test-reports 仓库没创建，git push 真跑会失败。</p></li><li><p>cron.yml 没装，系统还是手动 CLI 触发，不是 7×24。</p></li></ul><p>这五件事都不是写代码层的事，是业务层的事。Tool 是能力，Skill 是说明书，这五件填进去才长出业务：测哪些场景、SDK 用什么版本、报告归档到哪、什么频率跑。</p><p>代码层通用，业务层定义具体测什么，这是 27 讲那个“先做代码层再做业务层”决策的另一边。下面挨个填。</p><h2 id="把业务层填进去" tabindex="-1">把业务层填进去 <a class="header-anchor" href="#把业务层填进去" aria-label="Permalink to &quot;把业务层填进去&quot;">​</a></h2><h3 id="场景库-scenarios" tabindex="-1">场景库 scenarios/ <a class="header-anchor" href="#场景库-scenarios" aria-label="Permalink to &quot;场景库 scenarios/&quot;">​</a></h3><p>场景库是 Agent 拿到 Cron 触发或 CLI 手动触发后，真正知道该跑什么的地方。每个场景一个Markdown 文件，自然语言描述，告诉 Agent：这个场景是哪个协议、用哪个故障类型注入到哪个节点、跑哪些 SDK 验证、通过失败标准是什么。</p><p>按 25 讲方案的 P0/P1/P2 分级，场景库目录长这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/1.png" alt=""></a></p><p>写第一个场景给 Claude Code 提示词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我在 ~/.hermes/skills/robustmq-chaos-test/scenarios/mqtt/ 下</span></span>
<span class="line"><span>写第一个场景 p0-broker-kill-leader.md。</span></span>
<span class="line"><span>格式:Markdown,自然语言描述,Agent 读完知道按 SKILL.md 的&quot;单场景五步&quot;怎么调 Tool。</span></span>
<span class="line"><span>具体内容:</span></span>
<span class="line"><span>- 场景名:p0-broker-kill-leader</span></span>
<span class="line"><span>- 协议:MQTT</span></span>
<span class="line"><span>- 优先级:P0(每次触发都跑)</span></span>
<span class="line"><span>- 集群:3 节点 RobustMQ,broker-1 是 Leader</span></span>
<span class="line"><span>- 故障:用 chaos.py inject broker-kill,target=broker-1,duration=30 秒</span></span>
<span class="line"><span>- SDK 矩阵:从 config.yml 读 P0 档的 SDK 列表</span></span>
<span class="line"><span>- 验证:故障期间只记录,Chaosd recover 后等 broker-1 健康检查 200,</span></span>
<span class="line"><span> 再等 60 秒,跑完整 SDK 矩阵的 basic-pubsub</span></span>
<span class="line"><span>- 通过标准:exit_code=0,lost=0,p99_ms&lt;500</span></span>
<span class="line"><span>- 失败处理:记录到 report,继续下一场景</span></span>
<span class="line"><span>写完不要解释,我直接看文件。</span></span></code></pre></div><p>提示词的关键是“Agent 读完知道怎么调 Tool”，场景描述不是给人看的文档，是给 Agent 看的可执行说明。Claude Code 跑完产出 30 行左右的 Markdown，我看一眼，主要确认两件：故</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>障类型和参数跟 chaos.py 接口对得上；通过标准的字段名（exit_code / lost / p99_ms）</span></span></code></pre></div><p>跟 client.py 返回的 JSON 对得上。</p><p>第一个场景写完之后，剩下几个场景套同样模板，只改协议、target、duration、SDK 矩阵这几个参数。每个场景独立成文件，Agent 一次只加载本轮要跑的那几个。</p><h3 id="报告模板-templates-report-md-j2" tabindex="-1">报告模板 templates/report.md.j2 <a class="header-anchor" href="#报告模板-templates-report-md-j2" aria-label="Permalink to &quot;报告模板 templates/report.md.j2&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report.py 第三步 git push 之前要把测试结果渲染成 Markdown，模板就是这个文件：</span></span>
<span class="line"><span>帮我写 ~/.hermes/skills/robustmq-chaos-test/templates/report.md.j2,</span></span>
<span class="line"><span>Jinja2 模板。</span></span>
<span class="line"><span>输入是 report.py 传进来的 run_data,字段包括:run_id / started_at /</span></span>
<span class="line"><span>ended_at / cluster_info / scenarios(每个 scenario 含 fault_info /</span></span>
<span class="line"><span>sdk_results / passed)。</span></span>
<span class="line"><span>模板要点:</span></span>
<span class="line"><span>- 顶部一段 summary,Run ID + 起止时间 + 整体 pass/fail</span></span>
<span class="line"><span>- 每个 scenario 一个二级标题,展开 fault 信息和 SDK 矩阵结果</span></span>
<span class="line"><span>- SDK 结果用 Markdown 表格,列:sdk / version / scenario /</span></span>
<span class="line"><span> exit_code / lost / p99_ms / passed</span></span>
<span class="line"><span>- 底部一段&quot;协议兼容性归因&quot;,按 25 讲那张归因表的逻辑套</span></span>
<span class="line"><span> (不同 SDK 不一致 → 协议实现问题;特定版本失败 → 版本兼容问题;</span></span>
<span class="line"><span> 全部失败 → broker 端问题)</span></span>
<span class="line"><span>- 别在模板里调 LLM,纯 Jinja2 语法</span></span>
<span class="line"><span>模板长度控制在 80 行以内。</span></span></code></pre></div><p>模板的灵魂是那段“协议兼容性归因”，25 讲那张归因表落到报告里，问题暴露和定位归因合在一份报告里给人看，这才是 25 讲方案“测试报告对外公开建立社区信任”那条决策的真实落</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>点。Claude Code 产出的模板我会改一处：{% if all_failed %} 那段加一句“如果三种</span></span></code></pre></div><p>归因都不命中，标记为待人工分析”，AI 在边界 case 上偷懒，我们得手动收一下。</p><h3 id="套件配置-config-yml" tabindex="-1">套件配置 config.yml <a class="header-anchor" href="#套件配置-config-yml" aria-label="Permalink to &quot;套件配置 config.yml&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chaos.py 读 Chaosd 端点、client.py 读 SDK 矩阵、report.py 读 GitHub 仓库地址，</span></span></code></pre></div><p>都从这个文件读：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ~/.hermes/skills/robustmq-chaos-test/config.yml</span></span>
<span class="line"><span>chaosd:</span></span>
<span class="line"><span> endpoint: &quot;http://127.0.0.1:31767&quot;</span></span>
<span class="line"><span>sdk_matrix:</span></span>
<span class="line"><span> p0:</span></span>
<span class="line"><span>   - sdk: python</span></span>
<span class="line"><span>     version: &quot;3.11&quot;</span></span>
<span class="line"><span>     scenarios: [basic-pubsub]</span></span>
<span class="line"><span>   - sdk: go</span></span>
<span class="line"><span>     version: &quot;1.21&quot;</span></span>
<span class="line"><span>     scenarios: [basic-pubsub]</span></span>
<span class="line"><span> p1:</span></span>
<span class="line"><span>   - sdk: python</span></span>
<span class="line"><span>     versions: [&quot;3.10&quot;, &quot;3.11&quot;, &quot;3.12&quot;]</span></span>
<span class="line"><span>     scenarios: [basic-pubsub, failover]</span></span>
<span class="line"><span>   - sdk: rust</span></span>
<span class="line"><span>     version: &quot;1.70&quot;</span></span>
<span class="line"><span>     scenarios: [basic-pubsub, failover]</span></span>
<span class="line"><span> p2:</span></span>
<span class="line"><span>   - sdk: python</span></span>
<span class="line"><span>     versions: [&quot;3.10&quot;, &quot;3.11&quot;, &quot;3.12&quot;]</span></span>
<span class="line"><span>   - sdk: go</span></span>
<span class="line"><span>     versions: [&quot;1.20&quot;, &quot;1.21&quot;]</span></span>
<span class="line"><span>   - sdk: rust</span></span>
<span class="line"><span>     versions: [&quot;1.70&quot;, &quot;1.75&quot;]</span></span>
<span class="line"><span>   - sdk: java</span></span>
<span class="line"><span>     versions: [&quot;11&quot;, &quot;17&quot;, &quot;21&quot;]</span></span>
<span class="line"><span>github:</span></span>
<span class="line"><span> reports_repo: &quot;git@github.com:&lt;​your-org&gt;/test-reports.git&quot;</span></span>
<span class="line"><span> deploy_key_path: &quot;~/.ssh/test-reports-deploy&quot;</span></span>
<span class="line"><span> branch: &quot;main&quot;</span></span></code></pre></div><p>P0 档刻意只放 2 个 SDK，P0 是基础保障线，跑得越快越好。大矩阵留给 P1/P2。这是 25 讲场景分级直接落到 SDK 矩阵的体现。</p><h3 id="github-deploy-key-和-test-reports-仓库" tabindex="-1">GitHub Deploy Key 和 test-reports 仓库 <a class="header-anchor" href="#github-deploy-key-和-test-reports-仓库" aria-label="Permalink to &quot;GitHub Deploy Key 和 test-reports 仓库&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deploy Key 这件事 25 讲拍过决策：只授写权限到 test-reports 单一仓库，私钥放~/.ssh，</span></span></code></pre></div><p>不进 .env 不进版本库。三步搞定。</p><p>第一步，生成密钥对：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh-keygen -t ed25519 -f ~/.ssh/test-reports-deploy \\</span></span>
<span class="line"><span>   -C &quot;robustmq-chaos-test deploy key&quot; -N &quot;&quot;</span></span>
<span class="line"><span>-N &quot;&quot; 是空 passphrase，因为这把 key 是给自动化系统用的，不能交互输入密码。</span></span>
<span class="line"><span>第二步，在 GitHub 上创建一个新的空仓库 test-reports（public，这是 25 讲方案“完全公</span></span></code></pre></div><p>开建立社区信任”那条决策的物理体现）。然后进 Settings → Deploy keys → Add deploy key，</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">把</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/test-reports-deploy.pub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 内容贴进去，勾选</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">第三步，初始化仓库本地状态，确保</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 第一次</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 能成功：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GIT_SSH_COMMAND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ssh -i ~/.ssh/test-reports-deploy&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​your-or</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/test-reports.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/test-reports-init</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/test-reports-init</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;# RobustMQ Quality Reports&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GIT_SSH_COMMAND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ssh -i ~/.ssh/test-reports-deploy&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;init&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 成功这一步，Deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 链路就活了，后面</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 跑出来的报告会一直</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 到</span></span></code></pre></div><p>这个仓库。</p><h3 id="cron-yml-三档调度" tabindex="-1">cron.yml 三档调度 <a class="header-anchor" href="#cron-yml-三档调度" aria-label="Permalink to &quot;cron.yml 三档调度&quot;">​</a></h3><p>cron.yml 把 P0/P1/P2 三档变成 Hermes 真实的定时任务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ~/.hermes/cron.yml</span></span>
<span class="line"><span>jobs:</span></span>
<span class="line"><span> - name: p0-mqtt-basic</span></span>
<span class="line"><span>   schedule: &quot;0 */2 * * *&quot;</span></span>
<span class="line"><span>   prompt: &quot;按 P0 跑一轮 MQTT 基础场景&quot;</span></span>
<span class="line"><span> - name: p0-mq9-basic</span></span>
<span class="line"><span>   schedule: &quot;30 */2 * * *&quot;</span></span>
<span class="line"><span>   prompt: &quot;按 P0 跑一轮 mq9 基础场景&quot;</span></span>
<span class="line"><span> - name: p1-daily-fault</span></span>
<span class="line"><span>   schedule: &quot;0 3 * * *&quot;</span></span>
<span class="line"><span>   prompt: &quot;按 P1 跑一轮故障场景,MQTT 和 mq9 都跑&quot;</span></span>
<span class="line"><span> - name: p2-weekly-matrix</span></span>
<span class="line"><span>   schedule: &quot;0 4 * * 0&quot;</span></span>
<span class="line"><span>   prompt: &quot;按 P2 跑一轮完整 SDK 矩阵&quot;</span></span></code></pre></div><p>P0 每两小时一次，MQTT 和 mq9 错开 30 分钟避免资源冲突。P1 每天凌晨 3 点跑一次故障场景。P2 每周日凌晨 4 点跑全量 SDK 矩阵。频率配置直接来自 25 讲场景分级表，prompt用自然语言写，Hermes 把 prompt 喂给 AI Agent，Agent 加载 robustmq-chaos-test Skill 后</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按 Procedure 跑，跟 27 讲 hermes CLI 手动触发走的是同一条路。</span></span></code></pre></div><h2 id="让-hermes-跑起来" tabindex="-1">让 Hermes 跑起来 <a class="header-anchor" href="#让-hermes-跑起来" aria-label="Permalink to &quot;让 Hermes 跑起来&quot;">​</a></h2><p>业务层填完，该看真东西了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/2.png" alt=""></a></p><h3 id="先看一眼-tool-和-skill-都加载了" tabindex="-1">先看一眼 Tool 和 Skill 都加载了 <a class="header-anchor" href="#先看一眼-tool-和-skill-都加载了" aria-label="Permalink to &quot;先看一眼 Tool 和 Skill 都加载了&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hermes /skills</span></span>
<span class="line"><span>robustmq-chaos-test       v1.0.0    chaos testing for RobustMQ</span></span>
<span class="line"><span>$ hermes /tools</span></span>
<span class="line"><span>cluster        集群启停</span></span>
<span class="line"><span>observability  观测数据收集</span></span>
<span class="line"><span>client         多语言 SDK 调度</span></span>
<span class="line"><span>chaos          故障注入和恢复</span></span>
<span class="line"><span>report         报告生成 + GitHub 提交</span></span>
<span class="line"><span>... (Hermes 自带 Tool 略)</span></span></code></pre></div><p>5 个 Tool 加 1 个 Skill 全部识别，Hermes 看到了它们。</p><h3 id="用对话跑一次完整测试" tabindex="-1">用对话跑一次完整测试 <a class="header-anchor" href="#用对话跑一次完整测试" aria-label="Permalink to &quot;用对话跑一次完整测试&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/3.png" alt=""></a></p><p>进交互模式，手动跑一遍 P0 场景，这一步是验证整个系统真的能闭环，等手动跑通，Cron就能放心装上自动跑。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ hermes</span></span>
<span class="line"><span>&gt; 按 P0 跑一轮 MQTT 基础场景</span></span></code></pre></div><p>下面是 Agent 真实跑出来的对话。每一轮 Agent 调一个 Tool，我把 Agent 的判断和 Tool 返回的关键字段贴一下，让你看到链路真的串起来。</p><p>第 1 轮，Agent 加载 Skill，做前置检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Loaded skill: robustmq-chaos-test</span></span>
<span class="line"><span>Calling cluster(action=&quot;status&quot;) ...</span></span>
<span class="line"><span>→ {&quot;running&quot;: false}</span></span>
<span class="line"><span>环境干净,可以起集群。</span></span></code></pre></div><p>第 2 轮，起集群：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Calling cluster(action=&quot;start&quot;) ...</span></span>
<span class="line"><span>→ {&quot;status&quot;: &quot;running&quot;, &quot;endpoint&quot;: &quot;127.0.0.1:1883&quot;,</span></span>
<span class="line"><span>  &quot;data_dirs&quot;: [&quot;/tmp/rmq-xxx-1&quot;, &quot;/tmp/rmq-xxx-2&quot;, &quot;/tmp/rmq-xxx-3&quot;]}</span></span>
<span class="line"><span>3 节点集群健康,broker-1 是 leader。</span></span>
<span class="line"><span>第 3 轮，加载 P0 场景库，选 p0-broker-kill-leader，打基线 snapshot：</span></span>
<span class="line"><span>Loaded scenario: scenarios/mqtt/p0-broker-kill-leader.md</span></span>
<span class="line"><span>Calling observability(action=&quot;snapshot&quot;) ...</span></span>
<span class="line"><span>→ {&quot;timestamp&quot;: &quot;...&quot;, &quot;metrics&quot;: {...}, &quot;logs&quot;: {...}​}</span></span></code></pre></div><ul><li>基线已记录。</li></ul><p>第 4 轮，注入故障：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Calling</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chaos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(action</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;inject&quot;,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fault_type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;broker-kill&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             target</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;broker-1&quot;,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> duration_seconds</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">→</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {&quot;fault_id&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fault-abc123&quot;,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;status&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;active&quot;}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">broker-1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 已被</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill,开始故障期</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SDK</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 测试</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">只记录,不判断</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">。</span></span></code></pre></div><p>第 5 轮，故障期 SDK 测试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Calling client(action=&quot;run&quot;, sdk=&quot;python&quot;, version=&quot;3.11&quot;,</span></span>
<span class="line"><span>              scenario=&quot;basic-pubsub&quot;, cluster_endpoint=&quot;127.0.0.1:2883&quot;) ...</span></span>
<span class="line"><span>→ {&quot;exit_code&quot;: 1, &quot;lost&quot;: 47, &quot;p99_ms&quot;: 2300, &quot;errors&quot;: [...]}</span></span>
<span class="line"><span>故障期 Python SDK 有丢消息,符合预期(只记录)。</span></span>
<span class="line"><span>Calling client(action=&quot;run&quot;, sdk=&quot;go&quot;, version=&quot;1.21&quot;, ...)</span></span>
<span class="line"><span>→ {&quot;exit_code&quot;: 1, &quot;lost&quot;: 52, &quot;p99_ms&quot;: 2100, ...}</span></span></code></pre></div><p>第 6 轮，故障窗口结束，Chaosd 自动 recover，等 broker-1 健康再等 60 秒，跑自愈验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Calling chaos(action=&quot;recover&quot;, fault_id=&quot;fault-abc123&quot;) ...</span></span>
<span class="line"><span>→ {&quot;status&quot;: &quot;recovered&quot;}</span></span>
<span class="line"><span>Calling cluster(action=&quot;status&quot;) ...</span></span>
<span class="line"><span>→ {&quot;healthy_brokers&quot;: 3}</span></span>
<span class="line"><span>broker-1 已恢复健康,等 60 秒进入自愈验证窗口。</span></span>
<span class="line"><span>... waiting 60s ...</span></span>
<span class="line"><span>Calling client(action=&quot;run&quot;, sdk=&quot;python&quot;, version=&quot;3.11&quot;, ...) ...</span></span>
<span class="line"><span>→ {&quot;exit_code&quot;: 0, &quot;lost&quot;: 0, &quot;p99_ms&quot;: 38}</span></span>
<span class="line"><span>Calling client(action=&quot;run&quot;, sdk=&quot;go&quot;, version=&quot;1.21&quot;, ...) ...</span></span>
<span class="line"><span>→ {&quot;exit_code&quot;: 0, &quot;lost&quot;: 0, &quot;p99_ms&quot;: 41}</span></span>
<span class="line"><span>所有 SDK 自愈验证通过。</span></span></code></pre></div><p>第 7 轮，生成报告并 push 到 GitHub，然后停集群：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Calling report(action=&quot;generate_and_push&quot;, run_data={...}) ...</span></span>
<span class="line"><span>→ {&quot;json_path&quot;: &quot;...&quot;, &quot;markdown_path&quot;: &quot;...&quot;,</span></span>
<span class="line"><span>  &quot;github_url&quot;: &quot;https://github.com/&lt;​your-org&gt;/test-reports/blob/main/...&quot;,</span></span>
<span class="line"><span>  &quot;run_passed&quot;: true}</span></span>
<span class="line"><span>报告已 push:https://github.com/&lt;​your-org&gt;/test-reports/blob/main/2026/05/03/p0-bro</span></span>
<span class="line"><span>Calling cluster(action=&quot;stop&quot;) ...</span></span>
<span class="line"><span>→ {&quot;status&quot;: &quot;stopped&quot;}</span></span></code></pre></div><ul><li>本轮完成。</li></ul><p>整轮 7 个动作走完。这就是 25 讲方案文档里那张时序图的真实运转，cron.yml 没装，我用CLI 手动触发了一次，但这条链路装上 Cron 之后一行代码不用改就变 7×24。</p><h2 id="接下来怎么变成-7×24" tabindex="-1">接下来怎么变成 7×24 <a class="header-anchor" href="#接下来怎么变成-7×24" aria-label="Permalink to &quot;接下来怎么变成 7×24&quot;">​</a></h2><p>到这里我们整体的开发就完成了，代码在：<a href="https://github.com/robustmq/robustmq/tree/main/chaos-test%E3%80%82%E5%80%BC%E5%BE%97%E5%81%9C%E4%B8%8B%E6%9D%A5%E5%A4%9A%E7%9C%8B%E4%B8%80%E7%9C%BC%E3%80%82" target="_blank" rel="noreferrer">https://github.com/robustmq/robustmq/tree/main/chaos-test。值得停下来多看一眼。</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/28/4.png" alt=""></a></p><p>这条链路上每一步都有迹可循。从 24 讲一句话需求，到 25 讲两份评审级文档，到 26-27 讲长出来的代码，到刚才填进去的业务层。任何代码、配置、判断，都能追溯到上游某条决策。这不是文档本身有多漂亮，这是工程链路活起来的样子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cron.yml 已经装好，Hermes 启动时会自动加载。系统现在正式从“对话触发”变成 7×24，代</span></span></code></pre></div><p>码一行不用改，系统就升级了。第一期通道仅 CLI（25 讲拍过的决策），飞书第二期接入，Procedure 一字不改。</p><p>到这一讲为止，从 24 讲理解 Hermes、25 讲两次翻译拆需求和方案、26 讲跑通 HelloWorld、27 讲让代码长出来、28 讲填业务层让系统活起来。整套打法在 RobustMQ 上跑完了一轮闭环。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲做了五件业务层的事：写场景库、写报告模板、填 config.yml、生成 Deploy Key 和test-reports 仓库、装 cron.yml 三档调度。每件事单独看都不复杂，合在一起把 27 讲那六段代码从“能调”变成“真跑”。</p><p>Tool 是能力，Skill 是说明书，场景才是业务。这是这一讲想留给你的最重要的一句话。代码层是通用 Hermes 编程，换个项目能复用；业务层是当前这个具体项目的定义，跟 RobustMQ绑死。先做代码层，再填业务层，工程上更稳。下次再做一个类似系统（给另一个开源项目加自动化测试），代码层 80% 能搬，业务层完全重写。</p><p>跑通系统不是终点。第二期飞书接入、更多场景库、Quality Dashboard 前端，都是在这条已经活起来的链路上往外长。但今天看着报告 push 进 GitHub 这一刻，值得停下来。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>回想你最近做过的一个项目，如果按这一讲的“代码层 vs 业务层”分一下，哪些代码是通用能力，哪些是业务定义？如果有一天要把这个项目搬到另一个公司、另一个客户、另一个相似场景，你估计代码层能搬多少、业务层要重写多少？</p><p>欢迎在留言区写下你的判断，我们一起练“代码层 vs 业务层”在工程上的肌肉记忆。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,83)])])}const k=a(t,[["render",e]]);export{d as __pageData,k as default};
